package com.bank.hr;

import java.util.*;
import java.util.logging.*;

public class AgeStatsDemo {
    private static final Logger log = Logger.getLogger("AgeStats");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> team = List.of(
            new Employee("Rajesh", 34),
            new Employee("Priya", 41),
            new Employee("Amit", 28));
        AgeStatsService service = new AgeStatsService();

        log.info(() -> "sum    = " + service.totalAge(team));
        log.info(() -> "average= " + service.averageAge(team));
        log.info(() -> "max    = " + service.maxAge(team));
        log.info(() -> "min    = " + service.minAge(team));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final int age;
        Employee(String name, int age) { this.name = name;
        this.age = age; }
    String getName() { return name; }
    int getAge() { return age; }
}

// ─── Would be in service/AgeStatsService.java ───
class AgeStatsService {
    int totalAge(List<Employee> team) {
        return team.stream().mapToInt(Employee::getAge).sum();   // int, 0 if empty
    }
    double averageAge(List<Employee> team) {
        return team.stream().mapToInt(Employee::getAge)
            .average().orElse(0.0);                              // OptionalDouble
    }
    int maxAge(List<Employee> team) {
        return team.stream().mapToInt(Employee::getAge)
            .max().orElseThrow();                                // OptionalInt
    }
    int minAge(List<Employee> team) {
        return team.stream().mapToInt(Employee::getAge)
            .min().orElseThrow();                                // OptionalInt
    }
}
